fication']==='Fake'?'selected':'' ?>>Fake</option></select></div><button class="button primary">Apply filters</button><a class="button secondary" href="<?= $e($url('admin/reports')) ?>">Reset</a></form>
<section class="report-stat-grid" aria-label="Report totals"><?php foreach([['Total interviews',$m['total_interviews'],'All booking states'],['Tool interviews',$m['tool_interviews'],'All booking states'],['Normal interviews',$m['normal_interviews'],'All booking states'],['Cancelled',$m['cancelled_interviews'],'Included in totals'],['Unique candidates',$m['unique_candidates'],'Across all booking states'],['Scheduled minutes',$m['scheduled_minutes'],'Booked interviews only']] as [$label,$value,$note]):?><article class="stat-card"><span class="stat-label"><?= $e($label) ?></span><strong class="stat-value"><?= $e(number_format((int)$value)) ?></strong><p><?= $e($note) ?></p></article><?php endforeach;?></section>
<div class="report-grid">
<section class="card report-wide"><div class="card-heading"><div><h2>Interview trend</h2><p><?= $report['monthly']?'Monthly':'Daily' ?> counts, including booked and cancelled interviews.</p></div></div><?php if(!$report['trend']):?><div class="empty-state"><h3>No interviews in selected range.</h3><p>Try another range or clear a filter.</p></div><?php else:?><div class="trend-chart"><svg viewBox="0 0 720 190" role="img" aria-label="Interview counts by <?= $report['monthly']?'month':'day' ?>"><?php $count=count($report['trend']);$slot=680/max(1,$count);foreach($report['trend'] as $idx=>$row):$height=$maxTrend?((int)$row['total']/$maxTrend)*140:0;$x=25+$idx*$slot;$y=160-$height;?><rect x="<?= $e(round($x,2)) ?>" y="<?= $e(round($y,2)) ?>" width="<?= $e(max(2,round($slot-4,2))) ?>" height="<?= $e(round($height,2)) ?>"><title><?= $e($row['bucket'].': '.$row['total'].' interviews') ?></title></rect><?php endforeach;?></svg></div><details class="report-table-detail"><summary>View trend data</summary><div class="table-scroll"><table><thead><tr><th scope="col">Period</th><th scope="col">Total</th><th scope="col">Booked</th><th scope="col">Cancelled</th></tr></thead><tbody><?php foreach($report['trend'] as $r):?><tr><td><?= $e($r['bucket']) ?></td><td><?= $e($r['total']) ?></td><td><?= $e($r['booked']) ?></td><td><?= $e($r['cancelled']) ?></td></tr><?php endforeach;?></tbody></table></div></details><?php endif;?></section>
<section class="card"><div class="card-heading"><div><h2>Type split</h2><p>All booking states.</p></div></div><div class="split-list"><div><span>Tool</span><strong><?= $e($m['tool_interviews']) ?></strong></div><div><span>Normal</span><strong><?= $e($m['normal_interviews']) ?></strong></div></div></section>
<section class="card report-wide"><div class="card-heading"><div><h2>Technology volume</h2><p>Counts reflect every active report filter.</p></div></div><?php if(!$report['technologies']):?><div class="empty-state"><h3>No technology activity in this range.</h3></div><?php else:?><div class="table-scroll"><table><thead><tr><th scope="col">Technology</th><th scope="col">Total</th><th scope="col">Tool</th><th scope="col">Normal</th><th scope="col">Cancelled</th></tr></thead><tbody><?php foreach($report['technologies'] as $r):?><tr><td class="table-primary"><?= $e($r['name']) ?></td><td><?= $e($r['total']) ?></td><td><?= $e($r['tool_count']) ?></td><td><?= $e($r['normal_count']) ?></td><td><?= $e($r['cancelled_count']) ?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<section class="card"><div class="card-heading"><div><h2>Classification</h2><p>Candidate-selected classification.</p></div></div><?php $classTotal=array_sum(array_column($report['classifications'],'interview_count'));?><div class="split-list"><?php foreach(['Genuine','Fake'] as $name):$matches=array_values(array_filter($report['classifications'],fn($r)=>$r['classification']===$name));$row=$matches[0]??['interview_count'=>0,'candidate_count'=>0];$percent=$classTotal?round($row['interview_count']*100/$classTotal,1):null;?><div><span><?= $e($name) ?><small><?= $e($row['candidate_count']) ?> unique candidates</small></span><strong><?= $e($row['interview_count']) ?><?= $percent!==null?' · '.$e($percent).'%':'' ?></strong></div><?php endforeach;?></div></section>
<section class="card report-wide"><div class="card-heading"><div><h2>Support workload</h2><p>Booked Tool interviews only.</p></div></div><?php if(!$report['support']):?><div class="empty-state"><h3>No support people are relevant to this range.</h3></div><?php else:?><div class="table-scroll"><table><thead><tr><th scope="col">Name</th><th scope="col">Tool interviews</th><th scope="col">Scheduled minutes</th><th scope="col">Average duration</th><th scope="col">Tool workload</th></tr></thead><tbody><?php foreach($report['support'] as $r):?><tr><td><span class="table-primary"><?= $e($r['name']) ?></span><?= !$r['active']?'<span class="table-secondary">Inactive</span>':'' ?></td><td><?= $e($r['tool_interviews']) ?></td><td><?= $e($r['scheduled_minutes']) ?></td><td><?= $e($r['tool_interviews']?$r['average_minutes'].' min':'—') ?></td><td><?= $e($r['workload_percent']!==null?$r['workload_percent'].'%':'—') ?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<section class="card report-wide"><div class="card-heading"><div><h2>Resource utilization</h2><p>Booked minutes divided by configured open business minutes.</p></div></div><?php if(!$report['resources']):?><div class="empty-state"><h3>No resources are relevant to this range.</h3></div><?php else:?><div class="table-scroll"><table><thead><tr><th scope="col">Resource</th><th scope="col">Type</th><th scope="col">Booked interviews</th><th scope="col">Booked minutes</th><th scope="col">Available minutes</th><th scope="col">Utilization</th></tr></thead><tbody><?php foreach($report['resources'] as $r):?><tr><td><span class="table-primary"><?= $e($r['name']) ?></span><?= !$r['active']?'<span class="table-secondary">Currently inactive</span>':'' ?></td><td><span class="badge <?= $r['resource_type']==='TOOL'?'purple':'neutral' ?>"><?= $e(ucfirst(strtolower($r['resource_type']))) ?></span></td><td><?= $e($r['booked_interviews']) ?></td><td><?= $e($r['booked_minutes']) ?></td><td><?= $e($r['available_minutes']) ?></td><td><?= $e($r['utilization']!==null?$r['utilization'].'%':'—') ?><?= $r['over_capacity']?' <span class="badge danger-badge">Review data</span>':'' ?></td></tr><?php endforeach;?></tbody></table></div><p class="card-footnote">Current business hours are applied to the selected historical period. Earlier hour or activation changes are not versioned, so historical capacity is an operational estimate. Capacity begins when each resource was created.</p><?php endif;?></section>
<section class="card"><div class="card-heading"><div><h2>Peak start times</h2><p>Booked interviews in 30-minute windows.</p></div></div><?php if(!$report['peaks']):?><div class="empty-state"><h3>No booked start times to compare.</h3></div><?php else:?><ol class="ranking-list"><?php foreach($report['peaks'] as $r):?><li><span><?= $e($r['label']) ?></span><strong><?= $e($r['interview_count']) ?></strong></li><?php endforeach;?></ol><?php endif;?></section>
<section class="card"><div class="card-heading"><div><h2>Cancellations</h2><p>Sources shown only where audit records identify them.</p></div></div><div class="split-list"><div><span>Total cancellations</span><strong><?= $e($m['cancelled_interviews']) ?></strong></div><div><span>Cancellation rate</span><strong><?= $e($report['sources']['rate']!==null?$report['sources']['rate'].'%':'—') ?></strong></div><div><span>Candidate / Admin</span><strong><?= $e($report['sources']['candidate'].' / '.$report['sources']['admin']) ?></strong></div><?php if($report['sources']['unattributed']):?><div><span>Source unavailable</span><strong><?= $e($report['sources']['unattributed']) ?></strong></div><?php endif;?></div></section>
</div>
<section class="report-definition"><h2>How these numbers are calculated</h2><p>Total, Tool, Normal, unique candidates, technology, and classification include every booking state whose scheduled start falls in the selected local date range. Cancelled is a subset of Total. Scheduled minutes, support workload, peak times, and utilization include only bookings currently in the Booked state.</p></section>
